use std::fs

fn digit_val(c: char) -> int {
    let b = c as int
    if b >= 48 && b <= 57 { b - 48 } else if b >= 65 && b <= 90 { b - 55 } else { b - 87 }
}

fn digit_char(d: int) -> char {
    if d < 10 { (48 + d) as u8 as char } else { (55 + d) as u8 as char }
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() < 3 {
            continue
        }
        let from: int = parts[1].parse::<int>().unwrap_or(10)
        let to: int = parts[2].parse::<int>().unwrap_or(10)
        let mut n: int = 0
        for c in parts[0].chars() {
            n = n * from + digit_val(c)
        }
        if n == 0 {
            println("0")
            continue
        }
        let mut digits: Vec<char> = []
        while n > 0 {
            digits.push(digit_char(n % to))
            n = n / to
        }
        let mut out = ""
        let mut i = digits.len()
        while i > 0 {
            i -= 1
            out = out + digits[i].to_string()
        }
        println(out)
    }
}

